head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > readOnlyBackgroundImgCSS]<br/>읽기 전용(readonly) 상태인 Cell 에 적용될 배경 이미지의 스타일(CSS)를 설정합니다.",
    "validation" : [
        "읽기 전용(readonly) 상태인 Cell 에 적용될 배경 이미지의 스타일(CSS)를 설정합니다.",
        "속성값은 컴포넌트의 style 속성에 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        readOnlyBackgroundImgCSS: con_readOnlyBackgroundImgCSS.getText(),
        dataList: "data:dlt_bind",
    };

    let cList = $c.gcm.createCList(properties);

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (col1, col2 를 readOnly 로 설정)
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" id="" style="width:500px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column1" value="name1(RO)"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column2" value="name2(RO)"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col1" readOnly="true" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col2" readOnly="true" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="70" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    scwin.btn_readOnlyBackgroundImgCSS_onclick();
}



scwin.btn_readOnlyBackgroundImgCSS_onclick = function () {
    // readOnly 컬럼(col1) 의 배경 스타일 확인
    let readOnlyCell = document.querySelector('td[id*="target1_cell_0_0"]');
    // 일반 컬럼(col3) 의 배경 스타일 확인
    let normalCell = document.querySelector('td[id*="target1_cell_0_2"]');

    if (readOnlyCell) {
        let bgColor = readOnlyCell.style.backgroundColor;
        let bgImage = readOnlyCell.style.backgroundImage;
        let bgRepeat = readOnlyCell.style.backgroundRepeat;
        let bgPosition = readOnlyCell.style.backgroundPosition;
        wf_body_bottom.getObj("scwin").setReturnValue("readOnly Cell backgroundColor : " + bgColor);
        wf_body_bottom.getObj("scwin").setReturnValue("readOnly Cell backgroundImage : " + bgImage);
        wf_body_bottom.getObj("scwin").setReturnValue("readOnly Cell backgroundRepeat : " + bgRepeat);
        wf_body_bottom.getObj("scwin").setReturnValue("readOnly Cell backgroundPosition : " + bgPosition);
    }

    if (normalCell) {
        let bgImage = normalCell.style.backgroundImage;
        wf_body_bottom.getObj("scwin").setReturnValue("normal Cell backgroundImage : " + bgImage);
    }
}
